// Passes through only bookings CREATED very recently.
// Guard 1 of 2: an old booking can never notify, whatever the dedupe store says.

const WINDOW_MINUTES = 15;   // must be comfortably wider than the poll interval

const cutoff = Date.now() - WINDOW_MINUTES * 60 * 1000;
const events = $input.first().json.collection || [];

return events
  .filter(e => e.created_at && new Date(e.created_at).getTime() >= cutoff)
  .map(e => ({
    json: {
      eventUri: e.uri,
      eventName: e.name,
      startTime: e.start_time,
      endTime: e.end_time,
      createdAt: e.created_at,
      location: e.location || {},
      memberships: e.event_memberships || []
    }
  }));

// Pairs each invitee response with its event and builds the Slack message.
// Pairs against "Skip Already Notified", NOT "Find New Bookings" - the dedupe
// node drops items, so indices only line up after it.

const HOST_TZ = 'America/Denver'; // set this to your own timezone

const out = [];
const items = $input.all();
const events = $('Skip Already Notified').all();

for (let i = 0; i < items.length; i++) {
  const ev = events[i].json;
  const invitees = items[i].json.collection || [];

  for (const p of invitees) {
    const inviteeTz = p.timezone || 'UTC';

    const fmt = (iso, zone) => {
      if (!iso) return 'N/A';
      return DateTime.fromISO(iso, { zone: 'utc' })
        .setZone(zone)
        .toFormat("ccc, dd LLL yyyy 'at' hh:mm a");
    };

    let duration = '';
    if (ev.startTime && ev.endTime) {
      const mins = Math.round(
        DateTime.fromISO(ev.endTime).diff(DateTime.fromISO(ev.startTime), 'minutes').minutes
      );
      duration = ' (' + mins + ' min)';
    }

    const loc = ev.location || {};
    let locationText = 'N/A';
    if (loc.join_url) locationText = '<' + loc.join_url + '|Join link>';
    else if (loc.location) locationText = loc.location;
    else if (loc.type) locationText = String(loc.type).replace(/_/g, ' ');

    const host = (ev.memberships || [])[0] || {};

    const qa = (p.questions_and_answers || [])
      .filter(q => q.answer && String(q.answer).trim())
      .map(q => '> *' + q.question + '*\n> ' + q.answer)
      .join('\n');

    const t = p.tracking || {};
    const utm = [t.utm_source, t.utm_medium, t.utm_campaign, t.utm_content]
      .filter(Boolean).join(' / ');

    const lines = [];
    lines.push(':calendar: *New Calendly Booking*');
    lines.push('*Event:* ' + (ev.eventName || 'N/A') + duration);
    lines.push('*Name:* ' + (p.name || 'N/A'));
    lines.push('*Email:* ' + (p.email || 'N/A'));
    if (p.text_reminder_number) lines.push('*Phone:* ' + p.text_reminder_number);
    lines.push('*Their time:* ' + fmt(ev.startTime, inviteeTz) + '  _(' + inviteeTz + ')_');
    if (inviteeTz !== HOST_TZ) {
      lines.push('*Your time:* ' + fmt(ev.startTime, HOST_TZ) + '  _(' + HOST_TZ + ')_');
    }
    lines.push('*Location:* ' + locationText);
    if (host.user_name) lines.push('*Host:* ' + host.user_name);
    if (utm) lines.push('*Source:* ' + utm);
    if (qa) lines.push('\n*Answers:*\n' + qa);

    const links = [];
    if (p.reschedule_url) links.push('<' + p.reschedule_url + '|Reschedule>');
    if (p.cancel_url) links.push('<' + p.cancel_url + '|Cancel>');
    if (links.length) lines.push('\n' + links.join('  -  '));

    out.push({
      json: {
        slackText: lines.join('\n'),
        eventUri: ev.eventUri,
        inviteeName: p.name || null,
        inviteeEmail: p.email || null,
        startTime: ev.startTime || null,
        bookedAt: ev.createdAt || null,
        inviteeTimezone: inviteeTz,
        eventName: ev.eventName || null
      }
    });
  }
}

return out;

// Builds the Google Sheets row and works out which monthly tab it belongs in.
// Reads from "Format Booking" because the Slack node upstream outputs Slack's
// API response, not our booking data.

const HOST_TZ = 'America/Denver'; // set this to your own timezone

// Which month's tab does a lead belong to? Based on WHEN IT WAS BOOKED.
// To file by MEETING date instead, swap `bookedAt` for `startTime` below.
const TAB_BASIS = 'bookedAt';

const rows = [];

for (const item of $('Format Booking').all()) {
  const j = item.json;

  const basisIso = j[TAB_BASIS] || new Date().toISOString();
  const basis = DateTime.fromISO(basisIso, { zone: 'utc' }).setZone(HOST_TZ);

  // "July-26" -> full month name, dash, two-digit year
  const sheetName = basis.toFormat('LLLL') + '-' + basis.toFormat('yy');

  // Date column shows the MEETING time, not the booking time
  const dateText = j.startTime
    ? DateTime.fromISO(j.startTime, { zone: 'utc' })
        .setZone(HOST_TZ)
        .toFormat('yyyy-MM-dd hh:mm a')
    : '';

  rows.push({
    json: {
      sheetName: sheetName,
      name: j.inviteeName || '',
      email: j.inviteeEmail || '',
      dateText: dateText
    }
  });
}

return rows;

// Decides whether this month's tab needs creating, and from which template.
// Outputs zero items when there's nothing to do - this branch is a dead end,
// so that is harmless.

const HOST_TZ = 'America/Denver'; // set this to your own timezone
const TEMPLATE_TAB = 'Template';   // hidden tab holding headers + dropdowns

const now = DateTime.now().setZone(HOST_TZ);
const target = now.toFormat('LLLL') + '-' + now.toFormat('yy');

const sheets = ($input.first().json.sheets || []).map(s => s.properties);

// Already exists - nothing to do.
if (sheets.some(s => s.title === target)) return [];

const tpl = sheets.find(s => s.title === TEMPLATE_TAB);
if (!tpl) return [];   // no Template tab: do nothing rather than crash the run

return [{
  json: {
    templateSheetId: tpl.sheetId,
    newTitle: target,
    insertIndex: sheets.length
  }
}];

// Current month's tab name, for the 1st-of-month pre-create run.

const HOST_TZ = 'America/Denver'; // set this to your own timezone
const now = DateTime.now().setZone(HOST_TZ);

return [{ json: { sheetName: now.toFormat('LLLL') + '-' + now.toFormat('yy') } }];
